// Reusable outbound WhatsApp send -- expected caller input:
//   { to: '<E.164 or WhatsApp ID>', messageType: 'text', text: '<body>', contextTag?: '<free-text audit label>' }
// contextTag is optional and purely for audit/log readability (e.g.
// 'gateway-test-reply') -- never used for any control-flow decision here.
// Only 'text' messages are supported this phase; template messages are a
// documented future extension (see docs/adrs/ADR-0010-whatsapp-outbound-messaging.md).
const input = $json || {};
const to = typeof input.to === 'string' ? input.to.trim() : '';
const messageType = input.messageType || 'text';
const text = typeof input.text === 'string' ? input.text : '';

let reason = null;
if (!to) {
  reason = 'Missing "to" (recipient WhatsApp ID / phone number).';
} else if (messageType !== 'text') {
  reason = `Unsupported messageType "${messageType}" -- only "text" is implemented.`;
} else if (!text.trim()) {
  reason = 'Missing "text" for a text message.';
}

return [{
  json: {
    valid: reason === null,
    reason,
    to,
    messageType,
    text,
    contextTag: input.contextTag || null,
  },
}];

return [{
  json: {
    success: false,
    error: { type: 'invalid_input', message: $json.reason },
  },
}];

// Meta WhatsApp Cloud API send-message contract:
// https://developers.facebook.com/docs/whatsapp/cloud-api/reference/messages
return [{
  json: {
    to: $json.to,
    contextTag: $json.contextTag,
    requestBody: {
      messaging_product: 'whatsapp',
      to: $json.to,
      type: 'text',
      text: { body: $json.text, preview_url: false },
    },
  },
}];

// "Send WhatsApp Message" has onError: continueRegularOutput, so a failed
// call surfaces as $json.error here rather than throwing -- same pattern
// as workflows/crm/03-ai-qualification.json's "Map AI Core Result".
const result = $json || {};

if (result.error) {
  const message = String((result.error && result.error.message) || result.error);
  return [{ json: { success: false, error: { type: 'meta_api_error', message } } }];
}

const messageId = (Array.isArray(result.messages) && result.messages[0] && result.messages[0].id) || null;
const waId = (Array.isArray(result.contacts) && result.contacts[0] && result.contacts[0].wa_id) || null;

return [{
  json: {
    success: true,
    messageId,
    to: waId,
  },
}];
